public class StringImmutabilityDemo {
    public static void main(String[] args) {
        String city = "San Francisco";

        // 1. Classic Mistake: Calling transformation without capturing result
        city.toUpperCase();
        System.out.println("After city.toUpperCase(): " + city); // "San Francisco"

        // 2. Correct Usage: Reassign or capture new reference
        String upperCity = city.toUpperCase();
        System.out.println("Original city: " + city);            // "San Francisco"
        System.out.println("Captured upperCity: " + upperCity);  // "SAN FRANCISCO"

        // 3. Concatenation creates a brand-new object
        String part1 = "Cloud";
        String part2 = "Native";
        String combined = part1 + part2;

        System.out.println("part1 unchanged: " + part1);
        System.out.println("combined is new: " + combined);

        // 4. Reassigning reference
        String message = "Initial";
        message = message + " Updated"; // New object allocated; reference updated
        System.out.println("message now points to: " + message);
    }
}

