practiceProblems.solutionCode:
public class CleanPhoneNumber {
    public static void main(String[] args) {
        String rawPhone = "(555) 123-4567";
        String digits = rawPhone.replace("(", "")
                                .replace(")", "")
                                .replace(" ", "")
                                .replace("-", "");
        System.out.println("Digits: " + digits);
    }
}

