practiceProblems.solutionCode:
public class PathBuilder {
    public static void main(String[] args) {
        String path = "root";
        for (int i = 1; i <= 3; i++) {
            path = path + "/" + i;
        }
        System.out.println("Final Path: " + path);
    }
}

